INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('82b2c6e3cb2d1cc4', 'brand_bonk_golf', '3ea4a2c6bf7f984c', 1, 1, 1, 'live', 'Off the couch, onto the course', 'A gift that gets him golfing, so everyone wins. Told by the wife, with a smile.', 'Wives and girlfriends buying for him', 'Any snapback, or the set', 'Wife voiceover', '["I love my husband, but I need the house to myself.", "Best gift I bought him this year.", "He has not been on the couch since."]', '[{"label": "Open · 0 to 3s", "text": "Couch, remote, hat lands on his chest."}, {"label": "Middle", "text": "Him trying it on, finding the marker. \"Wait, what is this?\""}, {"label": "Close", "text": "Out the door with clubs. \"Mutually beneficial.\""}]', 'Him asleep on the couch with the remote. She drops the hat on his chest.', 'Cut to him walking out the door with clubs, hat on. She waves.', '[]');
